import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import '../models/product.dart';
import '../models/retail_shop.dart';
import '../models/sales.dart';
import '../services/firestore_service.dart';
import '../services/sales_service.dart';
class SalesPage extends StatefulWidget{const SalesPage({super.key});@override State<SalesPage> createState()=>_SalesPageState();}
class _SalesPageState extends State<SalesPage>{final q=TextEditingController(),rate=TextEditingController(),paid=TextEditingController();DateTime date=DateTime.now();String? shopId,productId,assignedShop;String account='Cash';RetailShop? shop;bool retail=false,loading=true,saving=false;String? editId;
 @override void initState(){super.initState();loadProfile();}@override void dispose(){q.dispose();rate.dispose();paid.dispose();super.dispose();}
 Future<void> loadProfile()async{final u=FirebaseAuth.instance.currentUser;if(u!=null){final d=(await FirebaseFirestore.instance.collection('users').doc(u.uid).get()).data()??{};if(mounted)setState((){retail=d['role']=='retail_shop_user';assignedShop=d['shopId']?.toString();shopId=assignedShop;loading=false;});}else if(mounted)setState(()=>loading=false);}
 String fd(DateTime d)=>'${d.day.toString().padLeft(2,'0')}-${d.month.toString().padLeft(2,'0')}-${d.year}';
 Future<void> pick()async{final x=await showDatePicker(context:context,initialDate:date,firstDate:DateTime(2020),lastDate:DateTime(2100));if(x!=null&&mounted)setState(()=>date=x);}
 double numv(String s)=>double.tryParse(s.trim())??0;
 void clear(){q.clear();rate.clear();paid.clear();setState((){editId=null;date=DateTime.now();account='Cash';productId=null;});}
 Future<void> save(List<Product> products,List<RetailShop> shops)async{if(shop==null||productId==null){msg('Select retail shop and product.');return;}final qty=numv(q.text),r=numv(rate.text),p=numv(paid.text);if(qty<=0||r<0){msg('Enter valid quantity and rate.');return;}final pr=products.firstWhere((x)=>x.id==productId);final item=SaleItem(productId:pr.id,productName:pr.name,quantity:qty,unitPrice:r,amount:qty*r);final gross=item.amount,commission=SalesService.instance.calculateCommission([item],shop!.commissionPerBox),net=SalesService.instance.calculateNet(gross,commission);if(p>net){msg('Payment received cannot exceed net amount.');return;}final sale=Sale(id:editId??'',date:date,shopId:shop!.id,shopName:shop!.name,items:[item],grossAmount:gross,commission:commission,netAmount:net,paymentReceived:p,outstanding:SalesService.instance.calculateOutstanding(net,p),paymentStatus:SalesService.instance.paymentStatus(net,p),paymentAccount:account);setState(()=>saving=true);try{if(editId==null){await SalesService.instance.addSale(sale);msg('Sales transaction saved successfully.');}else{await SalesService.instance.updateSale(sale);final a=await FirestoreService.instance.isAdmin();msg(a?'Sales transaction updated successfully.':'Edit request sent to Admin for approval.');}clear();}catch(e){msg('Unable to save sale: $e');}finally{if(mounted)setState(()=>saving=false);}}
 void msg(String s){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));}
 void edit(Sale s,List<RetailShop> ss){final i=s.items.isEmpty?null:s.items.first;setState((){editId=s.id;date=s.date;shopId=s.shopId;shop=ss.where((x)=>x.id==s.shopId).firstOrNull;productId=i?.productId;q.text=i?.quantity.toString()??'';rate.text=i?.unitPrice.toString()??'';paid.text=s.paymentReceived.toString();account=s.paymentAccount.isEmpty?'Cash':s.paymentAccount;});}
 Future<void> del(Sale s)async{try{await SalesService.instance.deleteSale(s.id);final a=await FirestoreService.instance.isAdmin();msg(a?'Sales transaction deleted.':'Delete request sent to Admin for approval.');}catch(e){msg('Unable to delete sale: $e');}}
 @override Widget build(BuildContext context){if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));return Scaffold(appBar:AppBar(title:const Text('Sales')),body:StreamBuilder<List<Map<String,dynamic>>>(stream:FirestoreService.instance.stream('retailShops'),builder:(c,ss){if(!ss.hasData)return const Center(child:CircularProgressIndicator());final all=ss.data!.map((x)=>RetailShop.fromMap(x['id'].toString(),x)).where((x)=>x.active).toList();final shops=retail?all.where((x)=>x.id==assignedShop).toList():all;if(shopId!=null)shop=shops.where((x)=>x.id==shopId).firstOrNull;return StreamBuilder<List<Map<String,dynamic>>>(stream:FirestoreService.instance.stream('products'),builder:(c,ps){if(!ps.hasData)return const Center(child:CircularProgressIndicator());final products=ps.data!.map((x)=>Product.fromMap(x['id'].toString(),x)).where((x)=>x.active).toList();return ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[InkWell(onTap:pick,child:InputDecorator(decoration:const InputDecoration(labelText:'Date',border:OutlineInputBorder()),child:Text(fd(date)))),const SizedBox(height:12),DropdownButtonFormField<String>(initialValue:shopId,items:shops.map((x)=>DropdownMenuItem(value:x.id,child:Text(x.name))).toList(),onChanged:retail?null:(v)=>setState((){shopId=v;shop=shops.where((x)=>x.id==v).firstOrNull;}),decoration:const InputDecoration(labelText:'Retail Shop',border:OutlineInputBorder())),const SizedBox(height:12),DropdownButtonFormField<String>(initialValue:productId,items:products.map((x)=>DropdownMenuItem(value:x.id,child:Text(x.name))).toList(),onChanged:(v)=>setState(()=>productId=v),decoration:const InputDecoration(labelText:'Product',border:OutlineInputBorder())),const SizedBox(height:12),Row(children:[Expanded(child:TextField(controller:q,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Quantity',border:OutlineInputBorder()))),const SizedBox(width:10),Expanded(child:TextField(controller:rate,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Rate',border:OutlineInputBorder())))]),const SizedBox(height:12),TextField(controller:paid,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Payment Received',border:OutlineInputBorder())),const SizedBox(height:12),DropdownButtonFormField<String>(initialValue:account,items:const[DropdownMenuItem(value:'Cash',child:Text('Cash')),DropdownMenuItem(value:'Bank',child:Text('Bank'))],onChanged:(v)=>setState(()=>account=v??account),decoration:const InputDecoration(labelText:'Payment Account',border:OutlineInputBorder())),const SizedBox(height:14),SizedBox(width:double.infinity,height:48,child:FilledButton(onPressed:saving?null:()=>save(products,shops),child:Text(saving?'SAVING...':(editId==null?'SAVE SALES':'UPDATE SALES'))))]))),const SizedBox(height:16),StreamBuilder<List<Sale>>(stream:SalesService.instance.watchSales(),builder:(c,s){if(s.hasError)return Text('Error loading sales: ${s.error}');if(!s.hasData)return const CircularProgressIndicator();final list=s.data!.where((x)=>!retail||x.shopId==assignedShop).toList();return Column(children:[const Align(alignment:Alignment.centerLeft,child:Text('Sales Transactions',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold))),...list.map((x)=>Card(child:ListTile(title:Text(x.shopName),subtitle:Text('${fd(x.date)} • Net ₹${x.netAmount.toStringAsFixed(2)} • Paid ₹${x.paymentReceived.toStringAsFixed(2)}'),trailing:Wrap(children:[IconButton(onPressed:()=>edit(x,shops),icon:const Icon(Icons.edit_outlined)),IconButton(onPressed:()=>del(x),icon:const Icon(Icons.delete_outline))])))]);})]);});});}
}
